package com.enterprise.procurement.business;

import com.baomidou.mybatisplus.core.toolkit.Wrappers; import com.enterprise.procurement.dto.PurchaseRequestDtos; import com.enterprise.procurement.persistence.entity.*; import com.enterprise.procurement.persistence.mapper.*; import org.springframework.stereotype.Service; import org.springframework.transaction.annotation.Transactional; import java.math.BigDecimal; import java.time.LocalDateTime; import java.time.format.DateTimeFormatter; import java.util.*;

@Service public class PurchaseBusinessService {
 private final PurchaseRequestMapper requests; private final PurchaseRequestItemMapper requestItems; private final ApprovalRecordMapper approvals; private final PurchaseOrderMapper orders; private final PurchaseOrderItemMapper orderItems; private final InventoryStockMapper stock; private final InventoryTransactionMapper transactions; private final CatalogMapper catalog;
 public PurchaseBusinessService(PurchaseRequestMapper r,PurchaseRequestItemMapper ri,ApprovalRecordMapper a,PurchaseOrderMapper o,PurchaseOrderItemMapper oi,InventoryStockMapper s,InventoryTransactionMapper t,CatalogMapper c){requests=r;requestItems=ri;approvals=a;orders=o;orderItems=oi;stock=s;transactions=t;catalog=c;}
 private SystemUserRow user(String username){var u=catalog.user(username); if(u==null)throw new IllegalArgumentException("用户不存在"); return u;}
 public Long userId(String username){return user(username).getId();}
 private PurchaseRequestEntity request(Long id){var r=requests.selectById(id); if(r==null)throw new NoSuchElementException("采购申请不存在"); return r;}
 private List<PurchaseRequestItemEntity> items(Long id){return requestItems.byRequest(id);}
 @Transactional public PurchaseRequestEntity createDraft(String username,PurchaseRequestDtos.Create dto){var u=user(username); var r=new PurchaseRequestEntity(); r.setRequestNo("PR"+LocalDateTime.now().format(DateTimeFormatter.ofPattern("yyyyMMddHHmmssSSS")));r.setApplicantId(u.getId());r.setDepartmentId(u.getDepartmentId());r.setReason(dto.reason());r.setStatus("DRAFT");r.setVersion(0);r.setCreatedAt(LocalDateTime.now());r.setUpdatedAt(LocalDateTime.now());r.setTotalAmount(BigDecimal.ZERO); requests.insert(r); fillItems(r,dto.items()); return r;}
 private void fillItems(PurchaseRequestEntity r,List<PurchaseRequestDtos.Item> input){BigDecimal total=BigDecimal.ZERO; for(var in:input){var p=catalog.product(in.productId());if(p==null)throw new IllegalArgumentException("商品不存在: "+in.productId());var i=new PurchaseRequestItemEntity();i.setRequestId(r.getId());i.setProductId(p.getId());i.setProductName(p.getName());i.setQuantity(in.quantity());i.setUnitPrice(in.unitPrice());i.setAmount(in.unitPrice().multiply(BigDecimal.valueOf(in.quantity())));requestItems.insert(i);total=total.add(i.getAmount());}r.setTotalAmount(total);requests.updateById(r);}
 @Transactional public PurchaseRequestEntity updateDraft(Long id,String username,PurchaseRequestDtos.Update dto){var r=request(id);if(!r.getApplicantId().equals(user(username).getId())||!"DRAFT".equals(r.getStatus()))throw new IllegalStateException("仅草稿本人可编辑");requestItems.deleteByRequest(id);r.setReason(dto.reason());r.setUpdatedAt(LocalDateTime.now());fillItems(r,dto.items());return r;}
 @Transactional public void deleteDraft(Long id,String username){var r=request(id);if(!r.getApplicantId().equals(user(username).getId())||!"DRAFT".equals(r.getStatus()))throw new IllegalStateException("仅草稿本人可删除");requestItems.deleteByRequest(id);requests.deleteById(id);}
 @Transactional public PurchaseRequestEntity submit(Long id,String username){var r=request(id);if(!r.getApplicantId().equals(user(username).getId()))throw new IllegalStateException("无权提交");if(requests.transition(id,"DRAFT","PENDING",r.getVersion())!=1)throw new IllegalStateException("申请状态已变更");return request(id);}
 @Transactional public PurchaseRequestEntity withdraw(Long id,String username){var r=request(id);if(!r.getApplicantId().equals(user(username).getId()))throw new IllegalStateException("无权撤回");if(requests.transition(id,"PENDING","DRAFT",r.getVersion())!=1)throw new IllegalStateException("仅待审批申请可撤回");return request(id);}
 public List<PurchaseRequestEntity> list(String username){var u=user(username);return requests.byApplicant(u.getId());}
 public List<PurchaseRequestEntity> pending(String username){var u=user(username);return requests.selectList(Wrappers.<PurchaseRequestEntity>lambdaQuery().eq(PurchaseRequestEntity::getStatus,"PENDING").eq(u.getDepartmentId()!=null,PurchaseRequestEntity::getDepartmentId,u.getDepartmentId()));}
 @Transactional public PurchaseRequestEntity approve(Long id,String username,PurchaseRequestDtos.Approval dto){var r=request(id);var u=user(username);if(!Objects.equals(r.getDepartmentId(),u.getDepartmentId()))throw new IllegalStateException("仅本部门负责人可审批");String action=dto.action().toUpperCase(Locale.ROOT);if(!Set.of("APPROVE","REJECT").contains(action))throw new IllegalArgumentException("action 必须为 APPROVE 或 REJECT");String to="APPROVE".equals(action)?"APPROVED":"REJECTED";if(requests.transition(id,"PENDING",to,r.getVersion())!=1)throw new IllegalStateException("申请状态已变更");var a=new ApprovalRecordEntity();a.setRequestId(id);a.setApproverId(u.getId());a.setAction(action);a.setComment(dto.comment());a.setCreatedAt(LocalDateTime.now());approvals.insert(a);return request(id);}
 @Transactional public PurchaseOrderEntity createOrder(Long requestId,Long supplierId){var r=request(requestId);if(!"APPROVED".equals(r.getStatus()))throw new IllegalStateException("申请未审批通过");var s=catalog.supplier(supplierId);if(s==null)throw new IllegalArgumentException("供应商不存在");var o=new PurchaseOrderEntity();o.setOrderNo("PO"+LocalDateTime.now().format(DateTimeFormatter.ofPattern("yyyyMMddHHmmssSSS")));o.setRequestId(requestId);o.setSupplierId(supplierId);o.setTotalAmount(r.getTotalAmount());o.setStatus("CREATED");o.setVersion(0);o.setCreatedAt(LocalDateTime.now());o.setUpdatedAt(LocalDateTime.now());orders.insert(o);for(var ri:items(requestId)){var oi=new PurchaseOrderItemEntity();oi.setOrderId(o.getId());oi.setProductId(ri.getProductId());oi.setProductName(ri.getProductName());oi.setQuantity(ri.getQuantity());oi.setUnitPrice(ri.getUnitPrice());oi.setAmount(ri.getAmount());orderItems.insert(oi);}if(requests.transition(requestId,"APPROVED","PURCHASING",r.getVersion())!=1)throw new IllegalStateException("申请状态已变更");return o;}
 @Transactional public PurchaseOrderEntity delivered(Long id,Long operatorId){var o=orders.selectById(id);if(o==null)throw new NoSuchElementException("订单不存在");if(orders.transition(id,"CREATED","DELIVERED",o.getVersion())!=1)throw new IllegalStateException("订单已处理");for(var i:orderItems.byOrder(id)){var st=stock.selectById(i.getProductId());if(st==null){st=new InventoryStockEntity();st.setProductId(i.getProductId());st.setQuantity(0);st.setVersion(0);stock.insert(st);}if(stock.increment(st.getProductId(),i.getQuantity(),st.getVersion())!=1)throw new IllegalStateException("库存并发冲突");var tx=new InventoryTransactionEntity();tx.setProductId(i.getProductId());tx.setQuantity(i.getQuantity());tx.setType("IN");tx.setReferenceNo(o.getOrderNo());tx.setOperatorId(operatorId);tx.setCreatedAt(LocalDateTime.now());transactions.insert(tx);}return orders.selectById(id);}
 public List<InventoryStockEntity> stock(){return stock.selectList(null);} public List<InventoryTransactionEntity> transactions(){return transactions.recent();} public List<PurchaseOrderEntity> orderList(){return orders.selectList(Wrappers.<PurchaseOrderEntity>lambdaQuery().orderByDesc(PurchaseOrderEntity::getCreatedAt));} public PurchaseRequestEntity get(Long id){return request(id);} public List<PurchaseRequestItemEntity> requestItems(Long id){return items(id);} public PurchaseOrderEntity getOrder(Long id){return orders.selectById(id);}
}
